export const LANGS = Object.keys(DICT);

const EN_MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const MONTHS = {
  es: ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"],
  fr: ["janv.", "févr.", "mars", "avr.", "mai", "juin", "juil.", "août", "sept.", "oct.", "nov.", "déc."],
  de: ["Jan.", "Feb.", "März", "Apr.", "Mai", "Juni", "Juli", "Aug.", "Sept.", "Okt.", "Nov.", "Dez."],
  pt: ["jan.", "fev.", "mar.", "abr.", "mai.", "jun.", "jul.", "ago.", "set.", "out.", "nov.", "dez."],
};

// "Oct 4, 2:00 PM EDT" becomes the way that language writes it ("4 oct, 2:00 p. m. EDT", "4 oct. 14:00 EDT", ...).
export function localizeTime(lang, text) {
  const m = /^([A-Z][a-z]{2}) (\d{1,2}), (\d{1,2}):(\d{2}) (AM|PM)(.*)$/.exec(String(text));
  if (!m) return text;
  const i = EN_MONTHS.indexOf(m[1]);
  if (i < 0) return text;
  const day = m[2];
  const minutes = m[4];
  const zone = m[6] || "";
  const month = MONTHS[lang]?.[i] ?? m[1];
  if (lang === "es") return `${day} ${month}, ${m[3]}:${minutes} ${m[5] === "AM" ? "a. m." : "p. m."}${zone}`;
  const hours24 = String((Number(m[3]) % 12) + (m[5] === "PM" ? 12 : 0)).padStart(2, "0");
  if (lang === "de") return `${day}. ${month}, ${hours24}:${minutes} Uhr${zone}`;
  if (lang === "pt") return `${day} de ${month}, ${hours24}:${minutes}${zone}`;
  return `${day} ${month}, ${hours24}:${minutes}${zone}`;
}

export function normalizeLang(locale) {
  const code = String(locale || "").slice(0, 2).toLowerCase();
  return DICT[code] ? code : "en";
}

const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

function compile(en, translation) {
  const names = [];
  const pattern = en
    .split(/(\{\w+\})/)
    .map((part) => {
      const m = /^\{(\w+)\}$/.exec(part);
      if (m) {
        names.push(m[1]);
        return "(.+?)";
      }
      return escapeRe(part);
    })
    .join("");
  // Most specific wording first: "Auction ended: reserve not met — {title}" must win over "Auction ended: {title}".
  return { re: new RegExp("^" + pattern + "$", "s"), names, translation, weight: en.replace(/\{\w+\}/g, "").length };
}

const COMPILED = {};
for (const lang of LANGS) {
  COMPILED[lang] = Object.entries(DICT[lang])
    .map(([en, translation]) => compile(en, translation))
    .sort((a, b) => b.weight - a.weight);
}

export function placeholders(text) {
  return (String(text).match(/\{\w+\}/g) || []).sort().join(",");
}

export function translateText(text, lang) {
  if (typeof text !== "string" || !COMPILED[lang]) return text;
  for (const rule of COMPILED[lang]) {
    const m = rule.re.exec(text);
    if (!m) continue;
    let out = rule.translation;
    rule.names.forEach((name, i) => {
      const value = name === "time" ? localizeTime(lang, m[i + 1]) : m[i + 1];
      out = out.split("{" + name + "}").join(value);
    });
    return out;
  }
  return text;
}

export function translateEmailParts(lang, parts) {
  if (!COMPILED[lang]) return parts;
  return {
    subject: translateText(parts.subject, lang),
    heading: translateText(parts.heading, lang),
    lines: (parts.lines || []).map((line) => translateText(line, lang)),
    buttonLabel: translateText(parts.buttonLabel, lang),
  };
}

const FOOTERS = {
  en: { sent: (shop) => `Sent by ${shop} via Hellfire Auctions because you bid on this auction.`, manage: "Manage the emails you get" },
  es: { sent: (shop) => `Enviado por ${shop} a través de Hellfire Auctions porque pujaste en esta subasta.`, manage: "Administra los emails que recibes" },
  fr: { sent: (shop) => `Envoyé par ${shop} via Hellfire Auctions parce que vous avez enchéri sur cette enchère.`, manage: "Gérer les e-mails que vous recevez" },
  de: { sent: (shop) => `Gesendet von ${shop} über Hellfire Auctions, weil Sie bei dieser Auktion geboten haben.`, manage: "E-Mails verwalten, die Sie erhalten" },
  pt: { sent: (shop) => `Enviado por ${shop} via Hellfire Auctions porque você deu um lance neste leilão.`, manage: "Gerenciar os e-mails que você recebe" },
};

export function footerWords(lang) {
  return FOOTERS[lang] || FOOTERS.en;
}
